    ('plugin_clinic','sick_pass','issued_by','app','users'),
    ('plugin_clinic','sick_pass','student_id','app','students'),
    ('plugin_clinic','visit','student_id','app','students'),
    ('plugin_exams','exam','created_by','app','users'),
